<?php
function opt($n,$d=''){global $argv;$p='--'.$n.'=';foreach($argv as $a)if(strpos($a,$p)===0)return substr($a,strlen($p));return $d;}function bad($m){fwrite(STDERR,$m.PHP_EOL);exit(2);} $md=realpath(dirname(__DIR__,3));$id=opt('id');$src=opt('source');$tgt=opt('target');$type=opt('type');$why=opt('justification');if(!$id||!$src||!$tgt||!$type||!$why)bad('Required --id --source --target --type --justification');$f=fopen($md.'/records/WORK_RELATIONSHIP_REGISTRY.csv','a');fputcsv($f,array($id,$src,$tgt,$type,$why,opt('decision'),date(DATE_ATOM),opt('notes')));fclose($f);echo 'REGISTERED_RELATIONSHIP '.$id.PHP_EOL;
